-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql.
--
-- Armas de Genshin Impact: 246. Con stats, efecto por nivel, como
-- conseguirlas, materiales y personajes recomendados (guias de Game8).
--
-- Los datos son una copia de la base de datos tal y como estaba el 2026-09-15.
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada: los
-- favoritos, tier lists y guias de los usuarios que apuntan a estas filas se
-- conservan. Ojo: si has cambiado algo desde la app despues de esa fecha,
-- ejecutarlo lo devuelve a como estaba en la copia.
--
-- Estas armas no estaban en la copia de la base de datos (genshin_armas.sql no
-- llego a ejecutarse), asi que salen de los archivos: datos de Yatta y
-- recomendados de Game8.

--
-- PARTE 4 de 4 (43 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 4 partes, en cualquier orden.

insert into public.weapons (
  id, game_id, name, name_en, rarity, category, image_url, description, base_hp, base_atk, base_def, sub_stat_name, sub_stat_value, passive_name, passive_levels, how_to_get, ascension, good_for, recommended
)
values
  ('gi-w-11509', 'genshin-impact', 'Reflejo de las Tinieblas', 'Mistsplitter Reforged', '5', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Narukami.png', 'Una espada que centellea con una fría e intensa luz violeta. La palabra “reflejo” de su nombre se debe a los fragmentos del pasado que se reflejan en ella.', null, 674, null, 'Daño CRIT', '44,1%', 'Vaina cortatinieblas', '["Otorga un 12% de Bono de todos los tipos de Daño Elemental, así como el poder de los emblemas cortatinieblas. Dependiendo de si tiene 1, 2 o 3 emblemas cortatinieblas, el personaje obtiene un 8/16/28% de Bono de Daño Elemental perteneciente a su tipo elemental. En las siguientes situaciones, el personaje obtiene un emblema: al infligir Daño Elemental con Ataques Normales. El emblema dura 5 s; al realizar la Habilidad Definitiva. El emblema dura 10 s; cuando la Energía Elemental del personaje está por debajo del 100%. El emblema cortatinieblas obtenido de esta manera dura hasta que el personaje regenere toda su Energía Elemental. La duración de cada emblema cortatinieblas se calcula de manera independiente.","Otorga un 15% de Bono de todos los tipos de Daño Elemental, así como el poder de los emblemas cortatinieblas. Dependiendo de si tiene 1, 2 o 3 emblemas cortatinieblas, el personaje obtiene un 10/20/35% de Bono de Daño Elemental perteneciente a su tipo elemental. En las siguientes situaciones, el personaje obtiene un emblema: al infligir Daño Elemental con Ataques Normales. El emblema dura 5 s; al realizar la Habilidad Definitiva. El emblema dura 10 s; cuando la Energía Elemental del personaje está por debajo del 100%. El emblema cortatinieblas obtenido de esta manera dura hasta que el personaje regenere toda su Energía Elemental. La duración de cada emblema cortatinieblas se calcula de manera independiente.","Otorga un 18% de Bono de todos los tipos de Daño Elemental, así como el poder de los emblemas cortatinieblas. Dependiendo de si tiene 1, 2 o 3 emblemas cortatinieblas, el personaje obtiene un 12/24/42% de Bono de Daño Elemental perteneciente a su tipo elemental. En las siguientes situaciones, el personaje obtiene un emblema: al infligir Daño Elemental con Ataques Normales. El emblema dura 5 s; al realizar la Habilidad Definitiva. El emblema dura 10 s; cuando la Energía Elemental del personaje está por debajo del 100%. El emblema cortatinieblas obtenido de esta manera dura hasta que el personaje regenere toda su Energía Elemental. La duración de cada emblema cortatinieblas se calcula de manera independiente.","Otorga un 21% de Bono de todos los tipos de Daño Elemental, así como el poder de los emblemas cortatinieblas. Dependiendo de si tiene 1, 2 o 3 emblemas cortatinieblas, el personaje obtiene un 14/28/49% de Bono de Daño Elemental perteneciente a su tipo elemental. En las siguientes situaciones, el personaje obtiene un emblema: al infligir Daño Elemental con Ataques Normales. El emblema dura 5 s; al realizar la Habilidad Definitiva. El emblema dura 10 s; cuando la Energía Elemental del personaje está por debajo del 100%. El emblema cortatinieblas obtenido de esta manera dura hasta que el personaje regenere toda su Energía Elemental. La duración de cada emblema cortatinieblas se calcula de manera independiente.","Otorga un 24% de Bono de todos los tipos de Daño Elemental, así como el poder de los emblemas cortatinieblas. Dependiendo de si tiene 1, 2 o 3 emblemas cortatinieblas, el personaje obtiene un 16/32/56% de Bono de Daño Elemental perteneciente a su tipo elemental. En las siguientes situaciones, el personaje obtiene un emblema: al infligir Daño Elemental con Ataques Normales. El emblema dura 5 s; al realizar la Habilidad Definitiva. El emblema dura 10 s; cuando la Energía Elemental del personaje está por debajo del 100%. El emblema cortatinieblas obtenido de esta manera dura hasta que el personaje regenere toda su Energía Elemental. La duración de cada emblema cortatinieblas se calcula de manera independiente."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Guardamano viejo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112044.png","cantidad":3},{"nombre":"Engranaje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112047.png","cantidad":5},{"nombre":"Rama de coral del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114025.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Guardamano viejo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112044.png","cantidad":12},{"nombre":"Engranaje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112047.png","cantidad":18},{"nombre":"Rama enjoyada del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114026.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Guardamano gemelo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112045.png","cantidad":9},{"nombre":"Eje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112048.png","cantidad":9},{"nombre":"Rama enjoyada del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114026.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Guardamano gemelo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112045.png","cantidad":14},{"nombre":"Eje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112048.png","cantidad":18},{"nombre":"Rama de jade del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114027.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Guardamano célebre","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112046.png","cantidad":9},{"nombre":"Ojo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112049.png","cantidad":14},{"nombre":"Rama de jade del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114027.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Guardamano célebre","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112046.png","cantidad":18},{"nombre":"Ojo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112049.png","cantidad":27},{"nombre":"Rama dorada del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114028.png","cantidad":6}]}]'::jsonb, 'Sobre todo para Alhacén (Alhaitham), Kamisato Ayaka, Kamisato Ayato y Keqing. También va bien con Albedo, Jean, Kaedehara Kazuha, Viajero (Traveler), Bennett, Kaeya, Laila (Layla) y Xingchiu (Xingqiu).', '[{"id":"gi-alhaitham","grupo":"destacado"},{"id":"gi-ayaka","grupo":"destacado"},{"id":"gi-ayato","grupo":"destacado"},{"id":"gi-keqing","grupo":"destacado"},{"id":"gi-albedo","grupo":"otros"},{"id":"gi-jean","grupo":"otros"},{"id":"gi-kazuha","grupo":"otros"},{"id":"gi-traveler","grupo":"otros"},{"id":"gi-bennett","grupo":"otros"},{"id":"gi-kaeya","grupo":"otros"},{"id":"gi-layla","grupo":"otros"},{"id":"gi-xingqiu","grupo":"otros"}]'::jsonb),
  ('gi-w-14519', 'genshin-impact', 'Reflexión Iridiscente', 'Vivid Notions', '5', 'Catalizador', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Catalyst_VaresaTransformer.png', 'Un trofeo hecho con gemas de la Comunidad de la Feracidad y cristales de la Tribu Plumaflora. Se dice que perteneció a un luchador legendario.', null, 674, null, 'Daño CRIT', '44,1%', 'Deseo del arcoíris caído', '["Aumenta el ATQ en un 28%. Al realizar un Ataque Descendente, obtienes el efecto de “colores del alba”, el cual aumenta en un 28% el Daño CRIT de los Ataques Descendentes. Al usar una Habilidad Elemental o Definitiva, obtienes el efecto de “resplandor del crepúsculo”, el cual aumenta en un 40% el Daño CRIT de los Ataques Descendentes. Cada uno de estos efectos dura 15 s y finalizarán 0.1 s después de que el impacto contra el suelo del Ataque Descendente golpee al objetivo.","Aumenta el ATQ en un 35%. Al realizar un Ataque Descendente, obtienes el efecto de “colores del alba”, el cual aumenta en un 35% el Daño CRIT de los Ataques Descendentes. Al usar una Habilidad Elemental o Definitiva, obtienes el efecto de “resplandor del crepúsculo”, el cual aumenta en un 50% el Daño CRIT de los Ataques Descendentes. Cada uno de estos efectos dura 15 s y finalizarán 0.1 s después de que el impacto contra el suelo del Ataque Descendente golpee al objetivo.","Aumenta el ATQ en un 42%. Al realizar un Ataque Descendente, obtienes el efecto de “colores del alba”, el cual aumenta en un 42% el Daño CRIT de los Ataques Descendentes. Al usar una Habilidad Elemental o Definitiva, obtienes el efecto de “resplandor del crepúsculo”, el cual aumenta en un 60% el Daño CRIT de los Ataques Descendentes. Cada uno de estos efectos dura 15 s y finalizarán 0.1 s después de que el impacto contra el suelo del Ataque Descendente golpee al objetivo.","Aumenta el ATQ en un 49%. Al realizar un Ataque Descendente, obtienes el efecto de “colores del alba”, el cual aumenta en un 49% el Daño CRIT de los Ataques Descendentes. Al usar una Habilidad Elemental o Definitiva, obtienes el efecto de “resplandor del crepúsculo”, el cual aumenta en un 70% el Daño CRIT de los Ataques Descendentes. Cada uno de estos efectos dura 15 s y finalizarán 0.1 s después de que el impacto contra el suelo del Ataque Descendente golpee al objetivo.","Aumenta el ATQ en un 56%. Al realizar un Ataque Descendente, obtienes el efecto de “colores del alba”, el cual aumenta en un 56% el Daño CRIT de los Ataques Descendentes. Al usar una Habilidad Elemental o Definitiva, obtienes el efecto de “resplandor del crepúsculo”, el cual aumenta en un 80% el Daño CRIT de los Ataques Descendentes. Cada uno de estos efectos dura 15 s y finalizarán 0.1 s después de que el impacto contra el suelo del Ataque Descendente golpee al objetivo."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Colmillo joven","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112101.png","cantidad":3},{"nombre":"Fragmento de caparazón agrietado por el frío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112119.png","cantidad":5},{"nombre":"Decadencia del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114065.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Colmillo joven","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112101.png","cantidad":12},{"nombre":"Fragmento de caparazón agrietado por el frío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112119.png","cantidad":18},{"nombre":"Desconsuelo del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114066.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Colmillo veterano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112102.png","cantidad":9},{"nombre":"Fragmento de caparazón con calor residual","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112120.png","cantidad":9},{"nombre":"Desconsuelo del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114066.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Colmillo veterano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112102.png","cantidad":14},{"nombre":"Fragmento de caparazón con calor residual","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112120.png","cantidad":18},{"nombre":"Esplendor del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114067.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Colmillo de tirano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112103.png","cantidad":9},{"nombre":"Fragmento de caparazón prismaflamígero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112121.png","cantidad":14},{"nombre":"Esplendor del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114067.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Colmillo de tirano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112103.png","cantidad":18},{"nombre":"Fragmento de caparazón prismaflamígero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112121.png","cantidad":27},{"nombre":"Máscara divina del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114068.png","cantidad":6}]}]'::jsonb, 'Sobre todo para Varesa.', '[{"id":"gi-varesa","grupo":"destacado"}]'::jsonb),
  ('gi-w-11519', 'genshin-impact', 'Refulgencia de la Luna', 'Lightbearing Moonshard', '5', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_SilverwareSaw.png', 'Cuenta la leyenda que una Adeptus que vivía recluida en un manantial cristalino forjó esta espada con la luz lunar reflejada en un pozo, la cual solo revelaba su verdadera forma durante el crepúsculo y el amanecer.', null, 542, null, 'Daño CRIT', '88,2%', 'Legado de Lang Gan', '["La DEF aumenta en un 20%. Después de que el portador de esta arma use su Habilidad Elemental, el daño de la reacción de Cristalización Lunar aumentará en un 64% durante 5 s.","La DEF aumenta en un 25%. Después de que el portador de esta arma use su Habilidad Elemental, el daño de la reacción de Cristalización Lunar aumentará en un 80% durante 5 s.","La DEF aumenta en un 30%. Después de que el portador de esta arma use su Habilidad Elemental, el daño de la reacción de Cristalización Lunar aumentará en un 96% durante 5 s.","La DEF aumenta en un 35%. Después de que el portador de esta arma use su Habilidad Elemental, el daño de la reacción de Cristalización Lunar aumentará en un 112% durante 5 s.","La DEF aumenta en un 40%. Después de que el portador de esta arma use su Habilidad Elemental, el daño de la reacción de Cristalización Lunar aumentará en un 128% durante 5 s."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Eje dañado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112122.png","cantidad":3},{"nombre":"Condensado brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112134.png","cantidad":5},{"nombre":"Grano de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114021.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Eje dañado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112122.png","cantidad":12},{"nombre":"Condensado brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112134.png","cantidad":18},{"nombre":"Lámina de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114022.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Eje reforzado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112123.png","cantidad":9},{"nombre":"Fragmento de armadura brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112135.png","cantidad":9},{"nombre":"Lámina de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114022.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Eje reforzado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112123.png","cantidad":14},{"nombre":"Fragmento de armadura brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112135.png","cantidad":18},{"nombre":"Fragmento de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114023.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Eje refinado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112124.png","cantidad":9},{"nombre":"Casco brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112136.png","cantidad":14},{"nombre":"Fragmento de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114023.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Eje refinado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112124.png","cantidad":18},{"nombre":"Casco brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112136.png","cantidad":27},{"nombre":"Trozo de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114024.png","cantidad":6}]}]'::jsonb, 'Zibai, Chiori y Albedo.', '[{"id":"gi-zibai","grupo":"lista"},{"id":"gi-chiori","grupo":"lista"},{"id":"gi-albedo","grupo":"lista"}]'::jsonb),
  ('gi-w-14521', 'genshin-impact', 'Relicario de la Verdad', 'Reliquary of Truth', '5', 'Catalizador', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Catalyst_Sistrum.png', 'Un relicario hecho con oro y jade. Cuenta la leyenda que se encontraba consagrado en un templo situado en las profundidades de Tulaytulah, la Ciudad de los Zafiros.', null, 542, null, 'Daño CRIT', '88,2%', 'Esencia de la falsedad', '["La Prob. CRIT aumenta en un 8%. Al usar la Habilidad Elemental, el portador de esta arma obtiene el efecto de “secreto de lo falso”, el cual aumenta la Maestría Elemental en 80 pts. durante 12 s. Cuando el portador inflige daño de Florecimiento Lunar a un enemigo, obtiene el efecto de “luna de la verdad”, el cual aumenta el Daño CRIT en un 24% durante 4 s. Cuando secreto de lo falso y luna de la verdad están activos a la vez, sus efectos se potencian un 50%.","La Prob. CRIT aumenta en un 10%. Al usar la Habilidad Elemental, el portador de esta arma obtiene el efecto de “secreto de lo falso”, el cual aumenta la Maestría Elemental en 100 pts. durante 12 s. Cuando el portador inflige daño de Florecimiento Lunar a un enemigo, obtiene el efecto de “luna de la verdad”, el cual aumenta el Daño CRIT en un 30% durante 4 s. Cuando secreto de lo falso y luna de la verdad están activos a la vez, sus efectos se potencian un 50%.","La Prob. CRIT aumenta en un 12%. Al usar la Habilidad Elemental, el portador de esta arma obtiene el efecto de “secreto de lo falso”, el cual aumenta la Maestría Elemental en 120 pts. durante 12 s. Cuando el portador inflige daño de Florecimiento Lunar a un enemigo, obtiene el efecto de “luna de la verdad”, el cual aumenta el Daño CRIT en un 36% durante 4 s. Cuando secreto de lo falso y luna de la verdad están activos a la vez, sus efectos se potencian un 50%.","La Prob. CRIT aumenta en un 14%. Al usar la Habilidad Elemental, el portador de esta arma obtiene el efecto de “secreto de lo falso”, el cual aumenta la Maestría Elemental en 140 pts. durante 12 s. Cuando el portador inflige daño de Florecimiento Lunar a un enemigo, obtiene el efecto de “luna de la verdad”, el cual aumenta el Daño CRIT en un 42% durante 4 s. Cuando secreto de lo falso y luna de la verdad están activos a la vez, sus efectos se potencian un 50%.","La Prob. CRIT aumenta en un 16%. Al usar la Habilidad Elemental, el portador de esta arma obtiene el efecto de “secreto de lo falso”, el cual aumenta la Maestría Elemental en 160 pts. durante 12 s. Cuando el portador inflige daño de Florecimiento Lunar a un enemigo, obtiene el efecto de “luna de la verdad”, el cual aumenta el Daño CRIT en un 48% durante 4 s. Cuando secreto de lo falso y luna de la verdad están activos a la vez, sus efectos se potencian un 50%."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espora fúngica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112059.png","cantidad":3},{"nombre":"Trozo de hueso apagado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112131.png","cantidad":5},{"nombre":"Reminiscencia del oasis exuberante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114041.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Espora fúngica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112059.png","cantidad":12},{"nombre":"Trozo de hueso apagado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112131.png","cantidad":18},{"nombre":"Gracia del oasis exuberante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114042.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Polen fluorescente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112060.png","cantidad":9},{"nombre":"Restos centelleantes","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112132.png","cantidad":9},{"nombre":"Gracia del oasis exuberante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114042.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Polen fluorescente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112060.png","cantidad":14},{"nombre":"Restos centelleantes","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112132.png","cantidad":18},{"nombre":"Lamento del oasis exuberante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114043.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Polvo quistecristalino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112061.png","cantidad":9},{"nombre":"Hueso externo reluciente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112133.png","cantidad":14},{"nombre":"Lamento del oasis exuberante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114043.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Polvo quistecristalino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112061.png","cantidad":18},{"nombre":"Hueso externo reluciente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112133.png","cantidad":27},{"nombre":"Esencia del oasis exuberante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114044.png","cantidad":6}]}]'::jsonb, 'Nefer, Lauma y Columbina.', '[{"id":"gi-nefer","grupo":"lista"},{"id":"gi-lauma","grupo":"lista"},{"id":"gi-columbina","grupo":"lista"}]'::jsonb),
  ('gi-w-14512', 'genshin-impact', 'Reminiscencia de Tulaytulah', 'Tulaytullah''s Remembrance', '5', 'Catalizador', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Catalyst_Alaya.png', 'Una campana hecha de zafiro y plata pura. Su lejana reverberación es, paradójicamente, muy nítida.', null, 674, null, 'Daño CRIT', '44,1%', 'Lágrimas zafíreas sepultadas', '["La Vel. de Ataque Normal aumenta en un 10%. Tras usar una Habilidad Elemental, el daño de Ataque Normal aumenta en un 4.8% cada segundo durante 14 s. Además, tras golpear a un enemigo con un Ataque Normal, el daño de dicho ataque aumenta en un 9.6%, lo cual se puede activar una vez cada 0.3 s. Mientras este efecto está activo, el daño de Ataque Normal solo puede aumentar hasta un 48% de esta manera. Cuando el personaje abandona el campo de batalla, este efecto se elimina y, si se vuelve a usar la Habilidad Elemental, se eliminará el efecto anterior.","La Vel. de Ataque Normal aumenta en un 12.5%. Tras usar una Habilidad Elemental, el daño de Ataque Normal aumenta en un 6% cada segundo durante 14 s. Además, tras golpear a un enemigo con un Ataque Normal, el daño de dicho ataque aumenta en un 12%, lo cual se puede activar una vez cada 0.3 s. Mientras este efecto está activo, el daño de Ataque Normal solo puede aumentar hasta un 60% de esta manera. Cuando el personaje abandona el campo de batalla, este efecto se elimina y, si se vuelve a usar la Habilidad Elemental, se eliminará el efecto anterior.","La Vel. de Ataque Normal aumenta en un 15%. Tras usar una Habilidad Elemental, el daño de Ataque Normal aumenta en un 7.2% cada segundo durante 14 s. Además, tras golpear a un enemigo con un Ataque Normal, el daño de dicho ataque aumenta en un 14.4%, lo cual se puede activar una vez cada 0.3 s. Mientras este efecto está activo, el daño de Ataque Normal solo puede aumentar hasta un 72% de esta manera. Cuando el personaje abandona el campo de batalla, este efecto se elimina y, si se vuelve a usar la Habilidad Elemental, se eliminará el efecto anterior.","La Vel. de Ataque Normal aumenta en un 17.5%. Tras usar una Habilidad Elemental, el daño de Ataque Normal aumenta en un 8.4% cada segundo durante 14 s. Además, tras golpear a un enemigo con un Ataque Normal, el daño de dicho ataque aumenta en un 16.8%, lo cual se puede activar una vez cada 0.3 s. Mientras este efecto está activo, el daño de Ataque Normal solo puede aumentar hasta un 84% de esta manera. Cuando el personaje abandona el campo de batalla, este efecto se elimina y, si se vuelve a usar la Habilidad Elemental, se eliminará el efecto anterior.","La Vel. de Ataque Normal aumenta en un 20%. Tras usar una Habilidad Elemental, el daño de Ataque Normal aumenta en un 9.6% cada segundo durante 14 s. Además, tras golpear a un enemigo con un Ataque Normal, el daño de dicho ataque aumenta en un 19.2%, lo cual se puede activar una vez cada 0.3 s. Mientras este efecto está activo, el daño de Ataque Normal solo puede aumentar hasta un 96% de esta manera. Cuando el personaje abandona el campo de batalla, este efecto se elimina y, si se vuelve a usar la Habilidad Elemental, se eliminará el efecto anterior."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Espora fúngica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112059.png","cantidad":3},{"nombre":"Núcleo fúngico inerte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112062.png","cantidad":5},{"nombre":"Eco del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114045.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Espora fúngica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112059.png","cantidad":12},{"nombre":"Núcleo fúngico inerte","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112062.png","cantidad":18},{"nombre":"Resplandor del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114046.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Polen fluorescente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112060.png","cantidad":9},{"nombre":"Núcleo fúngico inactivo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112063.png","cantidad":9},{"nombre":"Resplandor del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114046.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Polen fluorescente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112060.png","cantidad":14},{"nombre":"Núcleo fúngico inactivo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112063.png","cantidad":18},{"nombre":"Sueño del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114047.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Polvo quistecristalino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112061.png","cantidad":9},{"nombre":"Núcleo fúngico robusto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112064.png","cantidad":14},{"nombre":"Sueño del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114047.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Polvo quistecristalino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112061.png","cantidad":18},{"nombre":"Núcleo fúngico robusto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112064.png","cantidad":27},{"nombre":"Pasado del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114048.png","cantidad":6}]}]'::jsonb, 'Trotamundos (Wanderer), Shikanoin Heizou y Ningguang.', '[{"id":"gi-wanderer","grupo":"lista"},{"id":"gi-heizou","grupo":"lista"},{"id":"gi-ningguang","grupo":"lista"}]'::jsonb),
  ('gi-w-11425', 'genshin-impact', 'Réquiem Abisal', 'Finale of the Deep', '4', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Vorpal.png', 'Una espada tan silenciosa como una llanura abisal. Parece aún más antigua que la época a la supuestamente pertenece.', null, 565, null, 'ATQ', '27,6%', 'Sublime final', '["Al usar la Habilidad Elemental, el ATQ aumenta en un 12% durante 15 s y otorga al personaje un “pacto vital” del 25% de su Vida Máx. Este efecto solo puede activarse una vez cada 10 s. Cuando el pacto vital se elimina, el ATQ aumenta durante 15 s en un 2.4% de la cantidad eliminada, hasta un máximo de 150 pts. de ATQ.","Al usar la Habilidad Elemental, el ATQ aumenta en un 15% durante 15 s y otorga al personaje un “pacto vital” del 25% de su Vida Máx. Este efecto solo puede activarse una vez cada 10 s. Cuando el pacto vital se elimina, el ATQ aumenta durante 15 s en un 3% de la cantidad eliminada, hasta un máximo de 187.5 pts. de ATQ.","Al usar la Habilidad Elemental, el ATQ aumenta en un 18% durante 15 s y otorga al personaje un “pacto vital” del 25% de su Vida Máx. Este efecto solo puede activarse una vez cada 10 s. Cuando el pacto vital se elimina, el ATQ aumenta durante 15 s en un 3.6% de la cantidad eliminada, hasta un máximo de 225 pts. de ATQ.","Al usar la Habilidad Elemental, el ATQ aumenta en un 21% durante 15 s y otorga al personaje un “pacto vital” del 25% de su Vida Máx. Este efecto solo puede activarse una vez cada 10 s. Cuando el pacto vital se elimina, el ATQ aumenta durante 15 s en un 4.2% de la cantidad eliminada, hasta un máximo de 262.5 pts. de ATQ.","Al usar la Habilidad Elemental, el ATQ aumenta en un 24% durante 15 s y otorga al personaje un “pacto vital” del 25% de su Vida Máx. Este efecto solo puede activarse una vez cada 10 s. Cuando el pacto vital se elimina, el ATQ aumenta durante 15 s en un 4.8% de la cantidad eliminada, hasta un máximo de 300 pts. de ATQ."]'::jsonb, 'Forja: se fabrica en el herrero con su plano', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Guardamano viejo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112044.png","cantidad":2},{"nombre":"Gota legamosa","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112086.png","cantidad":3},{"nombre":"Sedimento de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114053.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Guardamano viejo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112044.png","cantidad":8},{"nombre":"Gota legamosa","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112086.png","cantidad":12},{"nombre":"Sublimación de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114054.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Guardamano gemelo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112045.png","cantidad":6},{"nombre":"Cúmulo de légamo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112087.png","cantidad":6},{"nombre":"Sublimación de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114054.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Guardamano gemelo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112045.png","cantidad":9},{"nombre":"Cúmulo de légamo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112087.png","cantidad":12},{"nombre":"Manantial de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114055.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Guardamano célebre","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112046.png","cantidad":6},{"nombre":"Ánima Legamosa neonata","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112088.png","cantidad":9},{"nombre":"Manantial de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114055.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Guardamano célebre","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112046.png","cantidad":12},{"nombre":"Ánima Legamosa neonata","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112088.png","cantidad":18},{"nombre":"Esencia de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114056.png","cantidad":4}]}]'::jsonb, 'Sobre todo para Kamisato Ayaka, Kamisato Ayato, Jean, Keqing y Qiqi. También va bien con Clorinde y Xingchiu (Xingqiu).', '[{"id":"gi-ayaka","grupo":"destacado"},{"id":"gi-ayato","grupo":"destacado"},{"id":"gi-jean","grupo":"destacado"},{"id":"gi-keqing","grupo":"destacado"},{"id":"gi-qiqi","grupo":"destacado"},{"id":"gi-clorinde","grupo":"otros"},{"id":"gi-xingqiu","grupo":"otros"}]'::jsonb),
  ('gi-w-13425', 'genshin-impact', 'Retribución de la Justicia', 'Rightful Reward', '4', 'Lanza', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Pole_Vorpal.png', 'Una lanza cuya afilada punta está manchada con un resquicio de sangre fresca.', null, 565, null, 'Vida', '27,6%', 'Punta de lanza', '["Al recibir curación, el personaje recupera 8 pts. de Energía Elemental. Este efecto solo se puede activar una vez cada 10 s y puede ocurrir incluso cuando el personaje está en tu equipo pero no en uso.","Al recibir curación, el personaje recupera 10 pts. de Energía Elemental. Este efecto solo se puede activar una vez cada 10 s y puede ocurrir incluso cuando el personaje está en tu equipo pero no en uso.","Al recibir curación, el personaje recupera 12 pts. de Energía Elemental. Este efecto solo se puede activar una vez cada 10 s y puede ocurrir incluso cuando el personaje está en tu equipo pero no en uso.","Al recibir curación, el personaje recupera 14 pts. de Energía Elemental. Este efecto solo se puede activar una vez cada 10 s y puede ocurrir incluso cuando el personaje está en tu equipo pero no en uso.","Al recibir curación, el personaje recupera 16 pts. de Energía Elemental. Este efecto solo se puede activar una vez cada 10 s y puede ocurrir incluso cuando el personaje está en tu equipo pero no en uso."]'::jsonb, 'Forja: se fabrica en el herrero con su plano', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Engranaje de malla","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112083.png","cantidad":2},{"nombre":"Núcleo de la fisura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112089.png","cantidad":3},{"nombre":"Copa rota del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114057.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Engranaje de malla","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112083.png","cantidad":8},{"nombre":"Núcleo de la fisura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112089.png","cantidad":12},{"nombre":"Copa de vino del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114058.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Mecaengranaje recto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112084.png","cantidad":6},{"nombre":"Sinapsis extrínseca","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112090.png","cantidad":6},{"nombre":"Copa de vino del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114058.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Mecaengranaje recto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112084.png","cantidad":9},{"nombre":"Sinapsis extrínseca","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112090.png","cantidad":12},{"nombre":"Copa de plata del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114059.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Engranaje mecadinámico","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112085.png","cantidad":6},{"nombre":"Núcleo vital de otro mundo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112091.png","cantidad":9},{"nombre":"Copa de plata del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114059.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Engranaje mecadinámico","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112085.png","cantidad":12},{"nombre":"Núcleo vital de otro mundo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112091.png","cantidad":18},{"nombre":"Copa de oro del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114060.png","cantidad":4}]}]'::jsonb, 'Sobre todo para Zhongli (Arconte Geo), Candace y Thoma. También va bien con Chevreuse, Mika y Yaoyao.', '[{"id":"gi-zhongli","grupo":"destacado"},{"id":"gi-candace","grupo":"destacado"},{"id":"gi-thoma","grupo":"destacado"},{"id":"gi-chevreuse","grupo":"otros"},{"id":"gi-mika","grupo":"otros"},{"id":"gi-yaoyao","grupo":"otros"}]'::jsonb),
  ('gi-w-14515', 'genshin-impact', 'Reverberación de la Grulla', 'Crane''s Echoing Call', '5', 'Catalizador', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Catalyst_MountainGale.png', 'Un abanico hecho de jade esmeralda de gran pureza, y que aún parece contener un antiguo poder adéptico.', null, 741, null, 'ATQ', '16,5%', 'Precepto de las nubes', '["Cuando el portador de esta arma golpea a un enemigo con un Ataque Descendente, el daño que infligen los personajes cercanos del equipo con este tipo de ataque aumenta en un 28% durante 20 s. Cuando un personaje cercano del equipo golpea a un enemigo con un Ataque Descendente, el portador recupera 2.5 pts. de Energía Elemental. Solo se puede recuperar Energía Elemental una vez cada 0.7 s de esta manera, y el portador podrá recuperarla incluso cuando esté en tu equipo pero no en uso.","Cuando el portador de esta arma golpea a un enemigo con un Ataque Descendente, el daño que infligen los personajes cercanos del equipo con este tipo de ataque aumenta en un 41% durante 20 s. Cuando un personaje cercano del equipo golpea a un enemigo con un Ataque Descendente, el portador recupera 2.75 pts. de Energía Elemental. Solo se puede recuperar Energía Elemental una vez cada 0.7 s de esta manera, y el portador podrá recuperarla incluso cuando esté en tu equipo pero no en uso.","Cuando el portador de esta arma golpea a un enemigo con un Ataque Descendente, el daño que infligen los personajes cercanos del equipo con este tipo de ataque aumenta en un 54% durante 20 s. Cuando un personaje cercano del equipo golpea a un enemigo con un Ataque Descendente, el portador recupera 3 pts. de Energía Elemental. Solo se puede recuperar Energía Elemental una vez cada 0.7 s de esta manera, y el portador podrá recuperarla incluso cuando esté en tu equipo pero no en uso.","Cuando el portador de esta arma golpea a un enemigo con un Ataque Descendente, el daño que infligen los personajes cercanos del equipo con este tipo de ataque aumenta en un 67% durante 20 s. Cuando un personaje cercano del equipo golpea a un enemigo con un Ataque Descendente, el portador recupera 3.25 pts. de Energía Elemental. Solo se puede recuperar Energía Elemental una vez cada 0.7 s de esta manera, y el portador podrá recuperarla incluso cuando esté en tu equipo pero no en uso.","Cuando el portador de esta arma golpea a un enemigo con un Ataque Descendente, el daño que infligen los personajes cercanos del equipo con este tipo de ataque aumenta en un 80% durante 20 s. Cuando un personaje cercano del equipo golpea a un enemigo con un Ataque Descendente, el portador recupera 3.5 pts. de Energía Elemental. Solo se puede recuperar Energía Elemental una vez cada 0.7 s de esta manera, y el portador podrá recuperarla incluso cuando esté en tu equipo pero no en uso."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Pergamino guía","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112008.png","cantidad":3},{"nombre":"Aleta emplumada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112095.png","cantidad":5},{"nombre":"Perdigones de plomo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114017.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Pergamino guía","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112008.png","cantidad":12},{"nombre":"Aleta emplumada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112095.png","cantidad":18},{"nombre":"Perdigones de mercurio","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114018.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Pergamino hechizado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112009.png","cantidad":9},{"nombre":"Aleta lunar","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112096.png","cantidad":9},{"nombre":"Perdigones de mercurio","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114018.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Pergamino hechizado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112009.png","cantidad":14},{"nombre":"Aleta lunar","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112096.png","cantidad":18},{"nombre":"Perdigones de oro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114019.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Pergamino maldito","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112010.png","cantidad":9},{"nombre":"Aleta luzabisal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112097.png","cantidad":14},{"nombre":"Perdigones de oro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114019.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Pergamino maldito","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112010.png","cantidad":18},{"nombre":"Aleta luzabisal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112097.png","cantidad":27},{"nombre":"Perdigones primordiales","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114020.png","cantidad":6}]}]'::jsonb, 'Sobre todo para Xianyun (Preservadora).', '[{"id":"gi-xianyun","grupo":"destacado"}]'::jsonb),
  ('gi-w-12412', 'genshin-impact', 'Rey de los Mares', 'Luxurious Sea-Lord', '4', 'Mandoble', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Claymore_MillenniaTuna.png', 'El majestuoso rey del océano. Tras secarse, sirve como arma y también como comida de emergencia.', null, 454, null, 'ATQ', '55,1%', 'Victoria oceánica', '["Aumenta el daño infligido por la Habilidad Definitiva en un 12%. Cuando la Habilidad Definitiva golpea a un enemigo, hay una probabilidad del 100% de invocar unos atunes que atacan e infligen un Daño en el AdE equivalente al 100% del ATQ. Este efecto solo se puede activar una vez cada 15 s.","Aumenta el daño infligido por la Habilidad Definitiva en un 15%. Cuando la Habilidad Definitiva golpea a un enemigo, hay una probabilidad del 100% de invocar unos atunes que atacan e infligen un Daño en el AdE equivalente al 125% del ATQ. Este efecto solo se puede activar una vez cada 15 s.","Aumenta el daño infligido por la Habilidad Definitiva en un 18%. Cuando la Habilidad Definitiva golpea a un enemigo, hay una probabilidad del 100% de invocar unos atunes que atacan e infligen un Daño en el AdE equivalente al 150% del ATQ. Este efecto solo se puede activar una vez cada 15 s.","Aumenta el daño infligido por la Habilidad Definitiva en un 21%. Cuando la Habilidad Definitiva golpea a un enemigo, hay una probabilidad del 100% de invocar unos atunes que atacan e infligen un Daño en el AdE equivalente al 175% del ATQ. Este efecto solo se puede activar una vez cada 15 s.","Aumenta el daño infligido por la Habilidad Definitiva en un 24%. Cuando la Habilidad Definitiva golpea a un enemigo, hay una probabilidad del 100% de invocar unos atunes que atacan e infligen un Daño en el AdE equivalente al 200% del ATQ. Este efecto solo se puede activar una vez cada 15 s."]'::jsonb, 'Recompensa del evento «Moonlight Merriment»', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Condensado de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","cantidad":2},{"nombre":"Fragmento de hueso frágil","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112041.png","cantidad":3},{"nombre":"Grano de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114021.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Condensado de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","cantidad":8},{"nombre":"Fragmento de hueso frágil","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112041.png","cantidad":12},{"nombre":"Lámina de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114022.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Babas de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112003.png","cantidad":6},{"nombre":"Fragmento de hueso sólido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112042.png","cantidad":6},{"nombre":"Lámina de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114022.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Babas de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112003.png","cantidad":9},{"nombre":"Fragmento de hueso sólido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112042.png","cantidad":12},{"nombre":"Fragmento de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114023.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Esencia de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112004.png","cantidad":6},{"nombre":"Fragmento de hueso fosilizado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112043.png","cantidad":9},{"nombre":"Fragmento de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114023.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Esencia de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112004.png","cantidad":12},{"nombre":"Fragmento de hueso fosilizado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112043.png","cantidad":18},{"nombre":"Trozo de siderita oscura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114024.png","cantidad":4}]}]'::jsonb, 'Sobre todo para Diluc y Eula. También va bien con Noelle, Beidou, Chongyun, Xinyan, Dehya y Mavuika (Arconte Pyro).', '[{"id":"gi-diluc","grupo":"destacado"},{"id":"gi-eula","grupo":"destacado"},{"id":"gi-noelle","grupo":"otros"},{"id":"gi-beidou","grupo":"otros"},{"id":"gi-chongyun","grupo":"otros"},{"id":"gi-xinyan","grupo":"otros"},{"id":"gi-dehya","grupo":"otros"},{"id":"gi-mavuika","grupo":"otros"}]'::jsonb),
  ('gi-w-12416', 'genshin-impact', 'Rey del Mal', 'Akuoumaru', '4', 'Mandoble', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Claymore_Maria.png', 'La espada más querida del Rey del Mal. Aunque es enorme e imponente, al blandirla es sorprendentemente ligera.', null, 510, null, 'ATQ', '41,3%', 'Dominaolas de Watatsumi', '["El daño infligido por la Habilidad Definitiva del portador de esta arma aumenta en un 0.12% por cada punto de la Energía Elemental máxima total de todos los miembros del equipo. El daño puede aumentar hasta un 40% de esta forma.","El daño infligido por la Habilidad Definitiva del portador de esta arma aumenta en un 0.15% por cada punto de la Energía Elemental máxima total de todos los miembros del equipo. El daño puede aumentar hasta un 50% de esta forma.","El daño infligido por la Habilidad Definitiva del portador de esta arma aumenta en un 0.18% por cada punto de la Energía Elemental máxima total de todos los miembros del equipo. El daño puede aumentar hasta un 60% de esta forma.","El daño infligido por la Habilidad Definitiva del portador de esta arma aumenta en un 0.21% por cada punto de la Energía Elemental máxima total de todos los miembros del equipo. El daño puede aumentar hasta un 70% de esta forma.","El daño infligido por la Habilidad Definitiva del portador de esta arma aumenta en un 0.24% por cada punto de la Energía Elemental máxima total de todos los miembros del equipo. El daño puede aumentar hasta un 80% de esta forma."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Guardamano viejo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112044.png","cantidad":2},{"nombre":"Garra oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112056.png","cantidad":3},{"nombre":"Rama de coral del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114025.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Guardamano viejo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112044.png","cantidad":8},{"nombre":"Garra oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112056.png","cantidad":12},{"nombre":"Rama enjoyada del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114026.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Guardamano gemelo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112045.png","cantidad":6},{"nombre":"Garra afilada oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112057.png","cantidad":6},{"nombre":"Rama enjoyada del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114026.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Guardamano gemelo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112045.png","cantidad":9},{"nombre":"Garra afilada oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112057.png","cantidad":12},{"nombre":"Rama de jade del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114027.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Guardamano célebre","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112046.png","cantidad":6},{"nombre":"Garra fantasmal oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112058.png","cantidad":9},{"nombre":"Rama de jade del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114027.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Guardamano célebre","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112046.png","cantidad":12},{"nombre":"Garra fantasmal oculta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112058.png","cantidad":18},{"nombre":"Rama dorada del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114028.png","cantidad":4}]}]'::jsonb, 'Diluc, Razor, Beidou, Chongyun, Xinyan, Eula y Dehya.', '[{"id":"gi-diluc","grupo":"lista"},{"id":"gi-razor","grupo":"lista"},{"id":"gi-beidou","grupo":"lista"},{"id":"gi-chongyun","grupo":"lista"},{"id":"gi-xinyan","grupo":"lista"},{"id":"gi-eula","grupo":"lista"},{"id":"gi-dehya","grupo":"lista"}]'::jsonb),
  ('gi-w-15431', 'genshin-impact', 'Rompecadenas', 'Chain Breaker', '4', 'Arco', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Bow_Isikhulu.png', 'Un arco adornado con jade cuya cuerda parece estar siempre envuelta por un suave viento. Según una leyenda, fue forjado por un herrero dragón de una época muy antigua.', null, 565, null, 'ATQ', '27,6%', 'Balada plumafloral', '["Por cada personaje de Natlan o de tipo elemental distinto al del portador de esta arma que haya en el equipo, el ATQ de dicho portador aumenta en un 4.8%. Cuando haya 3 o más personajes con estas características, la Maestría Elemental del portador de esta arma aumenta en 24 pts.","Por cada personaje de Natlan o de tipo elemental distinto al del portador de esta arma que haya en el equipo, el ATQ de dicho portador aumenta en un 6%. Cuando haya 3 o más personajes con estas características, la Maestría Elemental del portador de esta arma aumenta en 30 pts.","Por cada personaje de Natlan o de tipo elemental distinto al del portador de esta arma que haya en el equipo, el ATQ de dicho portador aumenta en un 7.2%. Cuando haya 3 o más personajes con estas características, la Maestría Elemental del portador de esta arma aumenta en 36 pts.","Por cada personaje de Natlan o de tipo elemental distinto al del portador de esta arma que haya en el equipo, el ATQ de dicho portador aumenta en un 8.4%. Cuando haya 3 o más personajes con estas características, la Maestría Elemental del portador de esta arma aumenta en 42 pts.","Por cada personaje de Natlan o de tipo elemental distinto al del portador de esta arma que haya en el equipo, el ATQ de dicho portador aumenta en un 9.6%. Cuando haya 3 o más personajes con estas características, la Maestría Elemental del portador de esta arma aumenta en 48 pts."]'::jsonb, 'Forja: se fabrica en el herrero con su plano', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Aleta emplumada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112095.png","cantidad":3},{"nombre":"Colmillo joven","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112101.png","cantidad":2},{"nombre":"Reflexión espiritista vientonocturna","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114069.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Aleta emplumada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112095.png","cantidad":12},{"nombre":"Colmillo joven","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112101.png","cantidad":8},{"nombre":"Presentimiento espiritista vientonocturno","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114070.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Aleta lunar","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112096.png","cantidad":6},{"nombre":"Colmillo veterano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112102.png","cantidad":6},{"nombre":"Presentimiento espiritista vientonocturno","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114070.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Aleta lunar","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112096.png","cantidad":12},{"nombre":"Colmillo veterano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112102.png","cantidad":9},{"nombre":"Presagio espiritista vientonocturno","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114071.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Aleta luzabisal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112097.png","cantidad":9},{"nombre":"Colmillo de tirano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112103.png","cantidad":6},{"nombre":"Presagio espiritista vientonocturno","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114071.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Aleta luzabisal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112097.png","cantidad":18},{"nombre":"Colmillo de tirano","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112103.png","cantidad":12},{"nombre":"Revelación espiritista vientonocturna","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114072.png","cantidad":4}]}]'::jsonb, 'Sethos, Aloy, Kujou Sara, Yoimiya, Ganyu, Tartaglia (Childe), Fischl, Venti (Arconte Anemo) y Amber.', '[{"id":"gi-sethos","grupo":"lista"},{"id":"gi-aloy","grupo":"lista"},{"id":"gi-kujou-sara","grupo":"lista"},{"id":"gi-yoimiya","grupo":"lista"},{"id":"gi-ganyu","grupo":"lista"},{"id":"gi-tartaglia","grupo":"lista"},{"id":"gi-fischl","grupo":"lista"},{"id":"gi-venti","grupo":"lista"},{"id":"gi-amber","grupo":"lista"}]'::jsonb),
  ('gi-w-11504', 'genshin-impact', 'Rompemontañas', 'Summit Shaper', '5', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Kunwu.png', 'Según la leyenda, esta afilada espada, que representa la firma de cierto contrato, se usó para cortar los picos de las montañas.', null, 608, null, 'ATQ', '49,6%', 'Majestad dorada', '["Aumenta en un 20% la Protección de Escudo. Tras atacar a un enemigo, el ATQ aumenta en un 4% durante 8 s. Este efecto puede acumularse hasta 5 veces y activarse una vez cada 0.3 s. Además, al estar bajo la protección de un escudo, el efecto de aumento de ATQ aumenta en un 100%.","Aumenta en un 25% la Protección de Escudo. Tras atacar a un enemigo, el ATQ aumenta en un 5% durante 8 s. Este efecto puede acumularse hasta 5 veces y activarse una vez cada 0.3 s. Además, al estar bajo la protección de un escudo, el efecto de aumento de ATQ aumenta en un 100%.","Aumenta en un 30% la Protección de Escudo. Tras atacar a un enemigo, el ATQ aumenta en un 6% durante 8 s. Este efecto puede acumularse hasta 5 veces y activarse una vez cada 0.3 s. Además, al estar bajo la protección de un escudo, el efecto de aumento de ATQ aumenta en un 100%.","Aumenta en un 35% la Protección de Escudo. Tras atacar a un enemigo, el ATQ aumenta en un 7% durante 8 s. Este efecto puede acumularse hasta 5 veces y activarse una vez cada 0.3 s. Además, al estar bajo la protección de un escudo, el efecto de aumento de ATQ aumenta en un 100%.","Aumenta en un 40% la Protección de Escudo.. Tras atacar a un enemigo, el ATQ aumenta en un 8% durante 8 s. Este efecto puede acumularse hasta 5 veces y activarse una vez cada 0.3 s. Además, al estar bajo la protección de un escudo, el efecto de aumento de ATQ aumenta en un 100%."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","cantidad":3},{"nombre":"Daga de cacería","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112029.png","cantidad":5},{"nombre":"Arena brillante de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114013.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","cantidad":12},{"nombre":"Daga de cacería","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112029.png","cantidad":18},{"nombre":"Piedra reluciente de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114014.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","cantidad":9},{"nombre":"Daga del agente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112030.png","cantidad":9},{"nombre":"Piedra reluciente de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114014.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Máscara sucia","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112006.png","cantidad":14},{"nombre":"Daga del agente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112030.png","cantidad":18},{"nombre":"Reliquia de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114015.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","cantidad":9},{"nombre":"Daga larga del inspector","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112031.png","cantidad":14},{"nombre":"Reliquia de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114015.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Máscara amenazante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112007.png","cantidad":18},{"nombre":"Daga larga del inspector","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112031.png","cantidad":27},{"nombre":"Cuerpo divino de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114016.png","cantidad":6}]}]'::jsonb, 'Viajero (Traveler), Kaeya, Bennett, Qiqi, Keqing, Kamisato Ayaka y Kamisato Ayato.', '[{"id":"gi-traveler","grupo":"lista"},{"id":"gi-kaeya","grupo":"lista"},{"id":"gi-bennett","grupo":"lista"},{"id":"gi-qiqi","grupo":"lista"},{"id":"gi-keqing","grupo":"lista"},{"id":"gi-ayaka","grupo":"lista"},{"id":"gi-ayato","grupo":"lista"}]'::jsonb),
  ('gi-w-11405', 'genshin-impact', 'Rugido del León', 'Lion''s Roar', '4', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Rockkiller.png', 'Una afilada espada con una lujosa decoración que no compromete ni su resistencia ni su filo. El sonido de la misma cortando el aire es como el rugido de un león.', null, 510, null, 'ATQ', '41,3%', 'Perdición del fuego y el trueno', '["Aumenta en un 20% el daño contra los enemigos afectados por Pyro o Electro.","Aumenta en un 24% el daño contra los enemigos afectados por Pyro o Electro.","Aumenta en un 28% el daño contra los enemigos afectados por Pyro o Electro.","Aumenta en un 32% el daño contra los enemigos afectados por Pyro o Electro.","Aumenta en un 36% el daño contra los enemigos afectados por Pyro o Electro."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de evento', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Daga de cacería","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112029.png","cantidad":3},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","cantidad":2},{"nombre":"Arena brillante de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114013.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Daga de cacería","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112029.png","cantidad":12},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","cantidad":8},{"nombre":"Piedra reluciente de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114014.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Daga del agente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112030.png","cantidad":6},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","cantidad":6},{"nombre":"Piedra reluciente de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114014.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Daga del agente","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112030.png","cantidad":12},{"nombre":"Insignia de cuervo plateada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112036.png","cantidad":9},{"nombre":"Reliquia de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114015.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Daga larga del inspector","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112031.png","cantidad":9},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","cantidad":6},{"nombre":"Reliquia de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114015.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Daga larga del inspector","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112031.png","cantidad":18},{"nombre":"Insignia de cuervo dorada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112037.png","cantidad":12},{"nombre":"Cuerpo divino de Guyun","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114016.png","cantidad":4}]}]'::jsonb, 'Keqing, Kamisato Ayato, Kuki Shinobu y Durin.', '[{"id":"gi-keqing","grupo":"lista"},{"id":"gi-ayato","grupo":"lista"},{"id":"gi-kuki-shinobu","grupo":"lista"},{"id":"gi-durin","grupo":"lista"}]'::jsonb),
  ('gi-w-13516', 'genshin-impact', 'Ruinas Ensangrentadas', 'Bloodsoaked Ruins', '5', 'Lanza', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Pole_TummaLyhty.png', 'Una lanza que se tiñó de un color oscuro después de muchas batallas. Emite un brillo muy especial debido al reflejo de la azulada llama que cuelga de ella.', null, 674, null, 'Prob. CRIT', '22,1%', 'Ceremonia de lamentación', '["Tras usar la Habilidad Definitiva, el daño que inflige el portador de esta arma a los enemigos con la reacción de Electrocargado Lunar aumenta en un 36% durante 3.5 s. Además, tras causar una reacción de Electrocargado Lunar, el portador obtiene el efecto de “elegía de la desolación”, el cual aumenta el Daño CRIT en un 28% durante 6 s, y también recupera 12 pts. de Energía Elemental. Solo se puede recuperar Energía Elemental una vez cada 14 s de esta manera.","Tras usar la Habilidad Definitiva, el daño que inflige el portador de esta arma a los enemigos con la reacción de Electrocargado Lunar aumenta en un 48% durante 3.5 s. Además, tras causar una reacción de Electrocargado Lunar, el portador obtiene el efecto de “elegía de la desolación”, el cual aumenta el Daño CRIT en un 35% durante 6 s, y también recupera 13 pts. de Energía Elemental. Solo se puede recuperar Energía Elemental una vez cada 14 s de esta manera.","Tras usar la Habilidad Definitiva, el daño que inflige el portador de esta arma a los enemigos con la reacción de Electrocargado Lunar aumenta en un 60% durante 3.5 s. Además, tras causar una reacción de Electrocargado Lunar, el portador obtiene el efecto de “elegía de la desolación”, el cual aumenta el Daño CRIT en un 42% durante 6 s, y también recupera 14 pts. de Energía Elemental. Solo se puede recuperar Energía Elemental una vez cada 14 s de esta manera.","Tras usar la Habilidad Definitiva, el daño que inflige el portador de esta arma a los enemigos con la reacción de Electrocargado Lunar aumenta en un 72% durante 3.5 s. Además, tras causar una reacción de Electrocargado Lunar, el portador obtiene el efecto de “elegía de la desolación”, el cual aumenta el Daño CRIT en un 49% durante 6 s, y también recupera 15 pts. de Energía Elemental. Solo se puede recuperar Energía Elemental una vez cada 14 s de esta manera.","Tras usar la Habilidad Definitiva, el daño que inflige el portador de esta arma a los enemigos con la reacción de Electrocargado Lunar aumenta en un 84% durante 3.5 s. Además, tras causar una reacción de Electrocargado Lunar, el portador obtiene el efecto de “elegía de la desolación”, el cual aumenta el Daño CRIT en un 56% durante 6 s, y también recupera 16 pts. de Energía Elemental. Solo se puede recuperar Energía Elemental una vez cada 14 s de esta manera."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Distintivo desgastado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112125.png","cantidad":3},{"nombre":"Condensado brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112134.png","cantidad":5},{"nombre":"Ascuas del fuego de la larga noche","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114077.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Distintivo desgastado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112125.png","cantidad":12},{"nombre":"Condensado brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112134.png","cantidad":18},{"nombre":"Destello del fuego de la larga noche","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114078.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Distintivo sofisticado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112126.png","cantidad":9},{"nombre":"Fragmento de armadura brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112135.png","cantidad":9},{"nombre":"Destello del fuego de la larga noche","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114078.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Distintivo sofisticado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112126.png","cantidad":14},{"nombre":"Fragmento de armadura brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112135.png","cantidad":18},{"nombre":"Llama del fuego de la larga noche","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114079.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Distintivo escarchado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112127.png","cantidad":9},{"nombre":"Casco brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112136.png","cantidad":14},{"nombre":"Llama del fuego de la larga noche","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114079.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Distintivo escarchado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112127.png","cantidad":18},{"nombre":"Casco brumoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112136.png","cantidad":27},{"nombre":"Ardor del fuego de la larga noche","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114080.png","cantidad":6}]}]'::jsonb, 'Cyno, Flins y Shogun Raiden (Arconte).', '[{"id":"gi-cyno","grupo":"lista"},{"id":"gi-flins","grupo":"lista"},{"id":"gi-raiden","grupo":"lista"}]'::jsonb),
  ('gi-w-12432', 'genshin-impact', 'Sabiduría Fraguada', 'Flame-Forged Insight', '4', 'Mandoble', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Claymore_Polilith.png', 'Según las leyendas de cierta tribu, esta es una espada de defensa propia que los herreros del Pueblo de los Manantiales hicieron a medida para un niño que iba a emprender un viaje muy lejano. Este ejemplar parece ser una réplica de la gran espada de esa historia.', null, 510, null, 'Maestría Elemental', '165', 'Pensamiento floreciente', '["Al causar una reacción de Electrocargado, Electrocargado Lunar, Florecimiento, Florecimiento Lunar, Cristalización o Cristalización Lunar, restaura 12 pts. de Energía Elemental y la Maestría Elemental aumenta en 60 pts. durante 15 s. Este efecto solo puede ocurrir una vez cada 15 s y se puede activar incluso cuando el portador de esta arma está en tu equipo pero no en uso.","Al causar una reacción de Electrocargado, Electrocargado Lunar, Florecimiento, Florecimiento Lunar, Cristalización o Cristalización Lunar, restaura 15 pts. de Energía Elemental y la Maestría Elemental aumenta en 75 pts. durante 15 s. Este efecto solo puede ocurrir una vez cada 15 s y se puede activar incluso cuando el portador de esta arma está en tu equipo pero no en uso.","Al causar una reacción de Electrocargado, Electrocargado Lunar, Florecimiento, Florecimiento Lunar, Cristalización o Cristalización Lunar, restaura 18 pts. de Energía Elemental y la Maestría Elemental aumenta en 90 pts. durante 15 s. Este efecto solo puede ocurrir una vez cada 15 s y se puede activar incluso cuando el portador de esta arma está en tu equipo pero no en uso.","Al causar una reacción de Electrocargado, Electrocargado Lunar, Florecimiento, Florecimiento Lunar, Cristalización o Cristalización Lunar, restaura 21 pts. de Energía Elemental y la Maestría Elemental aumenta en 105 pts. durante 15 s. Este efecto solo puede ocurrir una vez cada 15 s y se puede activar incluso cuando el portador de esta arma está en tu equipo pero no en uso.","Al causar una reacción de Electrocargado, Electrocargado Lunar, Florecimiento, Florecimiento Lunar, Cristalización o Cristalización Lunar, restaura 24 pts. de Energía Elemental y la Maestría Elemental aumenta en 120 pts. durante 15 s. Este efecto solo puede ocurrir una vez cada 15 s y se puede activar incluso cuando el portador de esta arma está en tu equipo pero no en uso."]'::jsonb, 'Recompensa del evento «Sunspray Summer Resort»', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Condensado extramarino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112080.png","cantidad":2},{"nombre":"Fragmento de caparazón agrietado por el frío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112119.png","cantidad":3},{"nombre":"Decadencia del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114065.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Condensado extramarino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112080.png","cantidad":8},{"nombre":"Fragmento de caparazón agrietado por el frío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112119.png","cantidad":12},{"nombre":"Desconsuelo del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114066.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Fragmento extramarino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112081.png","cantidad":6},{"nombre":"Fragmento de caparazón con calor residual","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112120.png","cantidad":6},{"nombre":"Desconsuelo del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114066.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Fragmento extramarino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112081.png","cantidad":9},{"nombre":"Fragmento de caparazón con calor residual","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112120.png","cantidad":12},{"nombre":"Esplendor del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114067.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Cristalización cromática","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112082.png","cantidad":6},{"nombre":"Fragmento de caparazón prismaflamígero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112121.png","cantidad":9},{"nombre":"Esplendor del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114067.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Cristalización cromática","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112082.png","cantidad":12},{"nombre":"Fragmento de caparazón prismaflamígero","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112121.png","cantidad":18},{"nombre":"Máscara divina del Sagrado Señor delirante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114068.png","cantidad":4}]}]'::jsonb, 'Aino, Gaming, Kaveh, Dehya, Dori y Sayu.', '[{"id":"gi-aino","grupo":"lista"},{"id":"gi-gaming","grupo":"lista"},{"id":"gi-kaveh","grupo":"lista"},{"id":"gi-dehya","grupo":"lista"},{"id":"gi-dori","grupo":"lista"},{"id":"gi-sayu","grupo":"lista"}]'::jsonb),
  ('gi-w-11427', 'genshin-impact', 'Sable de la Dársena', 'The Dockhand''s Assistant', '4', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Mechanic.png', 'Una práctica herramienta de cortar que ya no se puede encontrar en prácticamente ningún sitio. Sus desafiladas cuchillas se pueden ir cambiando conforme se usan.', null, 510, null, 'Vida', '41,3%', 'Saloma de los barqueros', '["Al recibir o realizar curación, otorga una marca de tenacidad durante 30 s, acumulable hasta 3 marcas. Al usar la Habilidad Elemental o Definitiva, se consumen todas las marcas de tenacidad y se obtiene el efecto de “vigorización” durante 10 s. Por cada marca de tenacidad consumida, aumenta en 40 pts. la Maestría Elemental y regenera 2 pts. de Energía Elemental al portador de esta arma durante los 2 s después de obtener este efecto. El efecto de vigorización solo se puede activar una vez cada 15 s, y el personaje puede obtener marcas de tenacidad incluso cuando esté en tu equipo pero no en uso.","Al recibir o realizar curación, otorga una marca de tenacidad durante 30 s, acumulable hasta 3 marcas. Al usar la Habilidad Elemental o Definitiva, se consumen todas las marcas de tenacidad y se obtiene el efecto de “vigorización” durante 10 s. Por cada marca de tenacidad consumida, aumenta en 50 pts. la Maestría Elemental y regenera 2.5 pts. de Energía Elemental al portador de esta arma durante los 2 s después de obtener este efecto. El efecto de vigorización solo se puede activar una vez cada 15 s, y el personaje puede obtener marcas de tenacidad incluso cuando esté en tu equipo pero no en uso.","Al recibir o realizar curación, otorga una marca de tenacidad durante 30 s, acumulable hasta 3 marcas. Al usar la Habilidad Elemental o Definitiva, se consumen todas las marcas de tenacidad y se obtiene el efecto de “vigorización” durante 10 s. Por cada marca de tenacidad consumida, aumenta en 60 pts. la Maestría Elemental y regenera 3 pts. de Energía Elemental al portador de esta arma durante los 2 s después de obtener este efecto. El efecto de vigorización solo se puede activar una vez cada 15 s, y el personaje puede obtener marcas de tenacidad incluso cuando esté en tu equipo pero no en uso.","Al recibir o realizar curación, otorga una marca de tenacidad durante 30 s, acumulable hasta 3 marcas. Al usar la Habilidad Elemental o Definitiva, se consumen todas las marcas de tenacidad y se obtiene el efecto de “vigorización” durante 10 s. Por cada marca de tenacidad consumida, aumenta en 70 pts. la Maestría Elemental y regenera 3.5 pts. de Energía Elemental al portador de esta arma durante los 2 s después de obtener este efecto. El efecto de vigorización solo se puede activar una vez cada 15 s, y el personaje puede obtener marcas de tenacidad incluso cuando esté en tu equipo pero no en uso.","Al recibir o realizar curación, otorga una marca de tenacidad durante 30 s, acumulable hasta 3 marcas. Al usar la Habilidad Elemental o Definitiva, se consumen todas las marcas de tenacidad y se obtiene el efecto de “vigorización” durante 10 s. Por cada marca de tenacidad consumida, aumenta en 80 pts. la Maestría Elemental y regenera 4 pts. de Energía Elemental al portador de esta arma durante los 2 s después de obtener este efecto. El efecto de vigorización solo se puede activar una vez cada 15 s, y el personaje puede obtener marcas de tenacidad incluso cuando esté en tu equipo pero no en uso."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Condensado extramarino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112080.png","cantidad":2},{"nombre":"Reloj de bolsillo vetusto de Senescal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112092.png","cantidad":3},{"nombre":"Sedimento de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114053.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Condensado ext