on conflict (id) do update
  set game_id = excluded.game_id,
      name = excluded.name,
      name_en = excluded.name_en,
      rarity = excluded.rarity,
      category = excluded.category,
      image_url = excluded.image_url,
      description = excluded.description,
      base_hp = excluded.base_hp,
      base_atk = excluded.base_atk,
      base_def = excluded.base_def,
      sub_stat_name = excluded.sub_stat_name,
      sub_stat_value = excluded.sub_stat_value,
      passive_name = excluded.passive_name,
      passive_levels = excluded.passive_levels,
      how_to_get = excluded.how_to_get,
      ascension = excluded.ascension,
      good_for = excluded.good_for,
      recommended = excluded.recommended;

-- Comprobacion
select count(*) as armas, count(*) filter (where recommended is not null) as con_recomendados
from public.weapons where game_id = 'genshin-impact';
